37	    fn collect_from_pairs<I, K, V>(pairs: I) -> Self
38	    where
39	        I: IntoIterator<Item = (K, V)>,
40	        K: Into<String>,
41	        V: Into<String>,
42	    {
43	        let env = pairs
44	            .into_iter()
45	            .map(|(key, value)| (key.into(), value.into()))
46	            .collect::<HashMap<_, _>>();
47	        let mut diagnostics = Vec::new();
48	
49	        let proxy_details = PROXY_ENV_VARS
50	            .iter()
51	            .filter_map(|key| {
52	                let value = env.get(*key)?.trim();
53	                if value.is_empty() {
54	                    return None;
55	                }
56	
57	                let detail = match sanitize_proxy_value(value) {
58	                    Some(sanitized) => format!("{key} = {sanitized}"),
59	                    None => format!("{key} = invalid value"),
60	                };
61	                Some(detail)
62	            })
63	            .collect::<Vec<_>>();
64	        if !proxy_details.is_empty() {
65	            diagnostics.push(FeedbackDiagnostic {
66	                headline: "Proxy environment variables are set and may affect connectivity."
67	                    .to_string(),
68	                details: proxy_details,
69	            });
70	        }
71	
72	        if let Some(value) = env.get(OPENAI_BASE_URL_ENV_VAR).map(String::as_str) {
73	            let trimmed = value.trim();
74	            if !trimmed.is_empty() && trimmed.trim_end_matches('/') != DEFAULT_OPENAI_BASE_URL {
75	                let detail = match sanitize_url_for_display(trimmed) {
76	                    Some(sanitized) => format!("{OPENAI_BASE_URL_ENV_VAR} = {sanitized}"),
77	                    None => format!("{OPENAI_BASE_URL_ENV_VAR} = invalid value"),
78	                };
79	                diagnostics.push(FeedbackDiagnostic {
80	                    headline: "OPENAI_BASE_URL is set and may affect connectivity.".to_string(),
81	                    details: vec![detail],
82	                });
83	            }
84	        }
85	
86	        Self { diagnostics }
87	    }
