117	pub fn sanitize_url_for_display(raw: &str) -> Option<String> {
118	    let trimmed = raw.trim();
119	    if trimmed.is_empty() {
120	        return None;
121	    }
122	
123	    let Ok(mut url) = Url::parse(trimmed) else {
124	        return None;
125	    };
126	    let _ = url.set_username("");
127	    let _ = url.set_password(None);
128	    url.set_query(None);
129	    url.set_fragment(None);
130	    Some(url.to_string().trim_end_matches('/').to_string()).filter(|value| !value.is_empty())
131	}
