133	fn sanitize_proxy_value(raw: &str) -> Option<String> {
134	    if raw.contains("://") {
135	        return sanitize_url_for_display(raw);
136	    }
137	
138	    sanitize_url_for_display(&format!("http://{raw}"))
139	}
