160	struct RingBuffer {
161	    max: usize,
162	    buf: VecDeque<u8>,
163	}
164	
165	impl RingBuffer {
166	    fn new(capacity: usize) -> Self {
167	        Self {
168	            max: capacity,
169	            buf: VecDeque::with_capacity(capacity),
170	        }
171	    }
172	
173	    fn len(&self) -> usize {
174	        self.buf.len()
175	    }
176	
177	    fn push_bytes(&mut self, data: &[u8]) {
178	        if data.is_empty() {
179	            return;
180	        }
181	
182	        // If the incoming chunk is larger than capacity, keep only the trailing bytes.
183	        if data.len() >= self.max {
184	            self.buf.clear();
185	            let start = data.len() - self.max;
186	            self.buf.extend(data[start..].iter().copied());
187	            return;
188	        }
189	
190	        // Evict from the front if we would exceed capacity.
191	        let needed = self.len() + data.len();
192	        if needed > self.max {
193	            let to_drop = needed - self.max;
194	            for _ in 0..to_drop {
195	                let _ = self.buf.pop_front();
196	            }
197	        }
198	
199	        self.buf.extend(data.iter().copied());
200	    }
201	
202	    fn snapshot_bytes(&self) -> Vec<u8> {
203	        self.buf.iter().copied().collect()
204	    }
205	}
